using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace CorseVR.Editor {
public static class ContactsV7 {
 public static string Bake(){if(EditorApplication.isPlaying)throw new Exception("Edit required");var main=GameObject.Find("Maquis_35m").transform;var ext=GameObject.Find("Extension_Tour_Littoral").transform;var renderers=new[]{main.Find("01_Terrain_Chemin").GetComponentInChildren<MeshFilter>(),ext.Find("02_Terrain_Littoral/Sol_Chemin_Littoral").GetComponent<MeshFilter>()};int index=0;
  foreach(var f in renderers){var owner=index==0?main:ext;var points=new List<Vector4>();foreach(var group in owner.GetComponentsInChildren<LODGroup>()){if(group.name.StartsWith("Prairie_"))continue;var rs=group.GetLODs()[0].renderers.Where(r=>r).ToArray();if(rs.Length==0)continue;var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);float radius=Mathf.Clamp(Mathf.Max(b.extents.x,b.extents.z)*.3f,.16f,.6f);points.Add(new Vector4(group.transform.position.x,group.transform.position.z,radius,.28f));}var rocks=index==0?main.Find("10_Refonte_Botanique_V2/E_Roches"):ext.Find("04_Rochers_Littoral");foreach(Transform rock in rocks){var rs=rock.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);float radius=Mathf.Clamp(Mathf.Max(b.extents.x,b.extents.z)*.8f,.2f,2.2f);points.Add(new Vector4(b.center.x,b.center.z,radius,.46f));}
   var buckets=new Dictionary<Vector2Int,List<Vector4>>();foreach(var p in points){for(int x=Mathf.FloorToInt((p.x-p.z)/2);x<=Mathf.FloorToInt((p.x+p.z)/2);x++)for(int z=Mathf.FloorToInt((p.y-p.z)/2);z<=Mathf.FloorToInt((p.y+p.z)/2);z++){var key=new Vector2Int(x,z);if(!buckets.ContainsKey(key))buckets[key]=new List<Vector4>();buckets[key].Add(p);}}
   var mesh=UnityEngine.Object.Instantiate(f.sharedMesh);var vertices=mesh.vertices;var colors=mesh.colors;if(colors.Length!=vertices.Length)colors=Enumerable.Repeat(Color.white,vertices.Length).ToArray();for(int i=0;i<vertices.Length;i++){var v=f.transform.TransformPoint(vertices[i]);List<Vector4> near;colors[i].a=1;if(!buckets.TryGetValue(new Vector2Int(Mathf.FloorToInt(v.x/2),Mathf.FloorToInt(v.z/2)),out near))continue;foreach(var p in near){float d=new Vector2(v.x-p.x,v.z-p.y).magnitude/p.z;float occlusion=p.w*Mathf.Pow(Mathf.Clamp01(1-d),2);colors[i].a=Mathf.Min(colors[i].a,1-occlusion);}}mesh.colors=colors;mesh.name="Terrain_Contacts_V7_"+index;AssetDatabase.CreateAsset(mesh,"Assets/Prototype_Maquis/Art/FinitionV7/Meshes/Terrain_Contacts_"+index+".asset");f.sharedMesh=mesh;EditorUtility.SetDirty(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f);index++;}
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return "Two terrain meshes received subtle static contact pigment; collision meshes untouched";}
}
}
